#!/usr/bin/env python3
"""Inventory repository files without traversing private or generated runtime data."""

import collections
from pathlib import Path
import subprocess
import sys


INSTRUCTION_NAMES = {
    "AGENTS.md", "CLAUDE.md", "GEMINI.md", "ANCHOR.md", "NORTH_STAR.md",
    "SKILL.md", "CONSTITUTION.md", "copilot-instructions.md", ".cursorrules",
}
# Maintainer-owned exceptions approved for this cleanup. Review when these
# paths or producers change; generated files remain measured, never hand-edited.
GENERATED = {
    "website/Cargo.lock": "Cargo dependency resolution (line-cap exception)",
    "api/bun.lock": "Bun dependency resolution",
    "MLXRead.xcodeproj/project.pbxproj": "XcodeGen project.yml",
    "MLXRead.xcodeproj/project.xcworkspace/xcshareddata/swiftpm/Package.resolved": "SwiftPM",
    "MLXRead/Resources/Info.plist": "XcodeGen project.yml",
    "SystemVoiceProvider/Info.plist": "XcodeGen project.yml",
    "SystemVoiceProvider/SystemVoiceProvider.entitlements": "XcodeGen project.yml",
    "website/src/asset_hashes.rs": "website/scripts/hash-assets.mjs",
}
RUNTIME_DIRS = {"build", "dist", "target", "node_modules", ".wrangler", "var", "dist-pages"}


def git_paths(root, *args):
    output = subprocess.check_output(["git", "-C", str(root), "ls-files", "-z", *args])
    return {Path(p) for p in output.decode("utf-8").split("\0") if p}


def private_path(path):
    name = path.name
    return (
        (name == ".env" or name.startswith(".env.")) and name != ".env.example"
        or name == ".dev.vars" or name.startswith(".dev.vars.")
        or path.suffix in {".pem", ".key", ".p12", ".p8"}
        or name.startswith("sparkle_private_key")
        or path.as_posix() == "Config/Signing.local.xcconfig"
    )


def line_limit(path):
    instruction = (
        path.name in INSTRUCTION_NAMES or path.suffix == ".mdc"
        or path.name.endswith(".instructions.md")
    )
    return 799 if instruction else 2000


def classify(root, path):
    if private_path(path):
        return "PRIVATE", None, "credential content not read"
    full = root / path
    if full.is_symlink() or any((root / parent).is_symlink() for parent in path.parents):
        return "UNRESOLVED", None, "symlink target not followed"
    if not full.exists():
        return "MISSING", None, "tracked deletion; no working file to measure"
    if path.name == ".DS_Store":
        try:
            with full.open("rb") as handle:
                signature = handle.read(8)
        except OSError as error:
            return "UNRESOLVED", None, str(error)
        if signature == b"\x00\x00\x00\x01Bud1":
            return "BINARY", None, "Finder metadata; eight-byte signature checked, records not read"
        return "UNRESOLVED", None, "unrecognized Finder metadata signature"
    try:
        data = full.read_bytes()
        text = data.decode("utf-8")
        if "\0" in text:
            raise UnicodeError("NUL byte")
    except UnicodeError:
        png = path.suffix == ".png" and (
            path.parent == Path("MLXRead/Resources/Assets.xcassets/AppIcon.appiconset")
            or path.parent == Path("website/assets")
        )
        if png and data.startswith(b"\x89PNG\r\n\x1a\n"):
            return "BINARY", None, "approved PNG exclusion; no text-line count"
        return "UNRESOLVED", None, "binary or non-UTF-8 file needs a measurement decision"
    except OSError as error:
        return "UNRESOLVED", None, str(error)
    lines = text.count("\n") + int(bool(text) and not text.endswith("\n"))
    producer = GENERATED.get(path.as_posix())
    limit = line_limit(path)
    if path.as_posix() == "website/Cargo.lock":
        return "EXEMPT", lines, producer
    if lines > limit:
        return "OVER", lines, f"limit {limit}" + (f"; generated by {producer}" if producer else "")
    return "GENERATED" if producer else "TEXT", lines, producer or f"limit {limit}"


def inventory(root):
    paths = git_paths(root, "--cached", "--others", "--exclude-standard")
    # Git ignores some local agent files. Count applicable instructions at the
    # root and along source paths, without entering ignored runtime trees.
    directories = {Path(".")}
    for path in paths:
        directories.update(path.parents)
    for directory in directories:
        for name in INSTRUCTION_NAMES:
            path = directory / name
            if (root / path).is_file() or (root / path).is_symlink():
                paths.add(path)
    rows = [(path, *classify(root, path)) for path in sorted(paths)]
    ignored = git_paths(root, "--others", "--ignored", "--exclude-standard", "--directory")
    for path in sorted(ignored - paths):
        if path.name == ".DS_Store":
            rows.append((path, *classify(root, path)))
            continue
        reason = "ignored runtime/build output; content not read"
        resolved = private_path(path) or any(part in RUNTIME_DIRS for part in path.parts)
        if private_path(path):
            reason = "ignored credential content not read"
        rows.append((path, "IGNORED" if resolved else "UNRESOLVED", None, reason if resolved
                     else "unclassified ignored path; content not read"))
    return rows


def main():
    root = Path(__file__).resolve().parent.parent
    rows = inventory(root)
    for path, status, lines, reason in rows:
        print(f"{status:10} {str(lines) if lines is not None else '-':>5}  {path} ({reason})")
    counts = collections.Counter(row[1] for row in rows)
    print("Population:", ", ".join(f"{key}={value}" for key, value in sorted(counts.items())))
    failed = counts["OVER"] + counts["UNRESOLVED"]
    print("FAIL: limits unmet or unverified" if failed else "PASS: measured text fits limits with listed exceptions")
    return int(bool(failed))


if __name__ == "__main__":
    sys.exit(main())
